import { api,pickFile,saveFile,encodeBase64,decodeBase64,openExternal } from './api.mjs';
import { uid,escapeHTML as e,clone,filterPages,byteSize,makePage,makeDatabase,inlineMarkdown,toMarkdown,descendants,safeURL } from './core.mjs';
import { t,setLocale } from './i18n.mjs';
import { icon } from './icons.mjs';
import { templates } from './templates.mjs';

const state={config:null,pages:[],route:'home',page:null,dirty:false,saving:null,saveError:'',editSeq:0,query:'',tag:'',sort:'updated',favorites:false,expanded:new Set(),sidebar:false,view:'table',dbQuery:'',dbSort:'',dbDesc:false,preview:false,stats:null,status:null,undo:[],redo:[],focusBlock:null,menu:null,busy:false};
let saveTimer,searchTimer,toastTimer,draggedBlock=null;
const assetURLs=new Set();
const $=selector=>document.querySelector(selector);
const workspace=()=>state.config?.workspaces.find(w=>w.id===state.config.activeId);
const request=(action,data={})=>api(action,{workspaceId:state.config?.activeId,...data});
function excerptText(value){const node=document.createElement('span');node.innerHTML=inlineMarkdown(value,state.pages);return node.textContent||'';}
const date=value=>value?new Date(value).toLocaleDateString(t('dateFormat'),{month:'short',day:'numeric'}):'';
const button=(label,action,kind='plain',glyph='',extra='')=>`<button class="button ${kind}" ${action?`data-action="${action}"`:''} ${extra.includes('type=')?'':'type="button"'} ${extra}>${glyph?icon(glyph):''}<span>${e(label)}</span></button>`;
const iconButton=(label,action,glyph,extra='')=>{const className=extra.match(/class="([^"\n]+)"/)?.[1]||'';return `<button class="icon-button ${className}" type="button" aria-label="${e(label)}" title="${e(label)}" data-action="${action}" ${extra.replace(/class="[^"\n]+"/,'')}>${icon(glyph)}</button>`;};
const emptyState=(title,description,glyph='page')=>`<div class="empty-state">${icon(glyph,36)}<h3>${e(title)}</h3><p>${e(description)}</p></div>`;
const recoveryKey=()=>`qingjian:recovery:${state.config.activeId}:${state.page?.id}`;
function toast(message,error=false){clearTimeout(toastTimer);$('#toast-root').innerHTML=`<div class="toast ${error?'error':''}">${icon(error?'info':'check')}<span>${e(message)}</span></div>`;toastTimer=setTimeout(()=>$('#toast-root').replaceChildren(),error?7000:3500);}
function applyPreferences(){setLocale(state.config.preferences.language);const theme=state.config.preferences.theme;document.documentElement.dataset.theme=theme==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):theme;document.documentElement.dataset.font=state.config.preferences.font;}
function formatStorage(){return state.stats?byteSize(state.stats.total):'—';}
function pageEntry(p,depth=0){const children=state.pages.filter(c=>!c.deleted&&c.parentId===p.id),expanded=state.expanded.has(p.id);return `<div class="tree-entry ${state.route===p.id?'active':''}" style="--depth:${depth}"><button class="tree-toggle ${children.length?'':'invisible'}" data-action="expand" data-id="${p.id}" aria-label="${e(t('subpage'))}" aria-expanded="${expanded}">${icon(expanded?'down':'chevron',13)}</button><button class="page-nav" data-action="page" data-id="${p.id}"><span class="page-emoji">${e(p.icon)}</span><span>${e(p.title)}</span></button>${iconButton(t('subpage'),'subpage','plus',`data-id="${p.id}" class="tree-add"`)}</div>${expanded?children.map(c=>pageEntry(c,depth+1)).join(''):''}`;}
function sidebar(){const w=workspace(),active=state.pages.filter(p=>!p.deleted),faves=active.filter(p=>p.favorite);return `<aside class="sidebar ${state.sidebar?'visible':''}">
 <div class="brand"><div class="brand-mark">笺</div><div><strong>${t('app')}</strong><small>${t('tagline')}</small></div>${iconButton(t('close'),'sidebar','close','class="mobile-close"')}</div>
 <button class="workspace-switch" data-action="workspaceMenu"><span class="workspace-avatar">${e(w?.name?.slice(0,1)||'笺')}</span><span><strong>${e(w?.name||t('workspace'))}</strong><small>${t('personal')}</small></span>${icon('down',15)}</button>
 <nav class="main-nav"><button data-action="home" class="${state.route==='home'?'active':''}">${icon('home')}<span>${t('home')}</span></button><button data-action="search">${icon('search')}<span>${t('search')}</span><kbd>⌘ K</kbd></button><button data-action="templates">${icon('grid')}<span>${t('templates')}</span></button></nav>
 <div class="sidebar-scroll"><div class="section-label"><span>${t('favorites')}</span>${icon('star',13)}</div>${faves.length?faves.map(p=>`<button class="favorite-nav ${state.route===p.id?'active':''}" data-action="page" data-id="${p.id}"><span>${e(p.icon)}</span><span>${e(p.title)}</span></button>`).join(''):`<p class="sidebar-hint">${t('favorite')}</p>`}
 <div class="section-label pages-label"><span>${t('pages')}</span>${iconButton(t('newPage'),'newPage','plus')}</div>${active.filter(p=>!p.parentId||!active.some(x=>x.id===p.parentId)).map(p=>pageEntry(p)).join('')}
 <button class="new-page-nav" data-action="newPage">${icon('plus',16)}${t('newPage')}</button></div>
 <div class="sidebar-bottom"><button data-action="import">${icon('download')}<span>${t('import')}</span></button><button data-action="trash" class="${state.route==='trash'?'active':''}">${icon('trash')}<span>${t('trash')}</span></button><button data-action="settings">${icon('settings')}<span>${t('settings')}</span></button>
 <div class="storage-widget"><div><span class="status-dot"></span><span>${t('local')}</span><button data-action="settings" data-tab="data">${formatStorage()} ${icon('chevron',12)}</button></div><div class="storage-bar"><i style="width:${state.stats?Math.max(5,Math.min(70,100*state.stats.notes/(state.stats.total||1))):20}%"></i><b style="width:${state.stats?Math.min(25,100*state.stats.assets/(state.stats.total||1)):0}%"></b></div><small>${t('offlineReady')}</small></div></div>
 </aside><button class="sidebar-scrim ${state.sidebar?'visible':''}" data-action="sidebar" aria-label="${t('close')}"></button>`;}
function header(){const w=workspace(),p=state.page,doc=state.route!=='home'&&state.route!=='trash';return `<header class="topbar"><div class="breadcrumbs">${iconButton(t('toggleSidebar'),'sidebar','menu','class="mobile-menu"')}<span>${e(w?.name)}</span>${icon('chevron',12)}<strong>${doc?e(p?.title):t(state.route==='trash'?'trash':'home')}</strong></div><div class="topbar-actions"><span class="save-state ${state.saveError?'failed':''}" id="save-state">${state.saveError?`${icon('info',14)}${t('saveError')}`:state.saving?`${icon('clock',14)}${t('saving')}`:`<span class="status-dot"></span>${t('saved')}`}</span>${state.saveError?button(t('retry'),'retry','plain','restore'):''}${button(t('sync'),'sync','plain','sync',state.busy?'disabled':'')}${doc?iconButton(p?.favorite?t('unfavorite'):t('favorite'),'favorite','star',p?.favorite?'data-active="true"':''):''}${doc?iconButton(t('more'),'more','dots'):''}</div></header>`;}
function pageCard(p){const excerpt=p.database?`${p.database.rows.length} ${t('records')}`:(p.blocks?.find(b=>b.type==='paragraph')?.text||p.blocks?.[0]?.text||t('emptyHint'));return `<button class="page-card" data-action="page" data-id="${p.id}"><div class="card-top"><span class="card-emoji">${e(p.icon)}</span>${p.favorite?icon('star',14):''}</div><h3>${e(p.title)}</h3><p>${e(excerptText(excerpt).slice(0,80))}</p><div class="card-bottom"><span>${p.tags?.[0]?`<i class="tag-pill">${e(p.tags[0])}</i>`:t(p.database?'database':'paragraph')}</span><time>${date(p.updatedAt)}</time></div></button>`;}
function home(){const pages=state.pages.filter(p=>!p.deleted),recent=[...pages].sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt)).slice(0,4),tags=[...new Set(pages.flatMap(p=>p.tags??[]))];let filtered=filterPages(pages,state.query).filter(p=>(!state.favorites||p.favorite)&&(!state.tag||p.tags.includes(state.tag)));filtered.sort(state.sort==='title'?(a,b)=>a.title.localeCompare(b.title,'zh'):(a,b)=>b.updatedAt.localeCompare(a.updatedAt));return `<div class="home-content"><div class="home-heading"><div><div class="eyebrow"><span class="tiny-square"></span>${t('goodDay')}<span class="date-caption">${new Date().toLocaleDateString(t('dateFormat'),{month:'long',day:'numeric',weekday:'long'})}</span></div><h1><span>${t('homeTitleStart')}</span><span>${t('homeTitleEnd')}</span></h1><p>${t('homeDesc')}</p></div>${button(t('newPage'),'newPage','primary','plus')}</div>
 <div class="quick-actions"><button data-action="newPage"><span class="quick-symbol green">${icon('plus',23)}</span><span><strong>${t('quickNote')}</strong><small>${t('blank')}</small></span>${icon('arrow',16)}</button><button data-action="templates"><span class="quick-symbol blue">${icon('grid',22)}</span><span><strong>${t('templatesTitle')}</strong><small>${t('journal')} · ${t('meeting')}</small></span>${icon('arrow',16)}</button><button data-action="import"><span class="quick-symbol amber">${icon('download',22)}</span><span><strong>${t('importTitle')}</strong><small>${t('notion')}</small></span>${icon('arrow',16)}</button></div>
 <section class="recent-section"><div class="section-heading"><h2>${icon('clock',17)}${t('recent')}</h2><span>${pages.length} ${t('pageCount')}</span></div><div class="recent-grid">${recent.map(pageCard).join('')||emptyState(t('empty'),t('emptyHint'))}</div></section>
 <section class="all-pages"><div class="library-toolbar"><div class="tabs"><button data-action="allPages" class="${!state.favorites?'selected':''}">${t('allPages')}<span>${pages.length}</span></button><button data-action="favoritesOnly" class="${state.favorites?'selected':''}">${t('favoritesOnly')}</button></div><div class="library-controls"><div class="search-field">${icon('search',16)}<input id="home-search" aria-label="${t('search')}" placeholder="${t('searchHint')}" value="${e(state.query)}"></div><select id="tag-filter" aria-label="${t('filterTag')}"><option value="">${t('allTags')}</option>${tags.map(tag=>`<option ${state.tag===tag?'selected':''}>${e(tag)}</option>`).join('')}</select><select id="home-sort" aria-label="${t('sort')}"><option value="updated">${t('sortUpdated')}</option><option value="title" ${state.sort==='title'?'selected':''}>${t('sortTitle')}</option></select></div></div>
 <div class="page-table"><div class="page-table-head"><span>${t('pages')}</span><span>${t('tag')}</span><span>${t('updated')}</span><span></span></div>${filtered.map(p=>`<div class="page-row"><button data-action="page" data-id="${p.id}"><span>${e(p.icon)}</span><strong>${e(p.title)}</strong>${p.database?`<span class="type-badge">${t('database')}</span>`:''}</button><div class="row-tags">${p.tags.slice(0,2).map(tag=>`<span class="tag-pill">${e(tag)}</span>`).join('')}</div><time>${date(p.updatedAt)}</time>${iconButton(t('favorite'),'rowFavorite','star',`data-id="${p.id}" ${p.favorite?'data-active="true"':''}`)}</div>`).join('')||emptyState(t('noResults'),t('noResultsHint'),'search')}</div></section>
 <footer class="home-footer"><span>${icon('git',15)}${state.status?.commit?state.status.commit.slice(0,7):t('localOnly')} <span>·</span> ${e(wLabel())}</span><button data-action="settings" data-tab="workspaces">${t('workspaces')}${icon('arrow',14)}</button></footer></div>`;}
function wLabel(){return workspace()?.remote?t('connected'):t('noRemote');}
function blockHTML(b,index){const locked=state.page.locked||state.preview||state.busy;const controls=locked?'':`<div class="block-controls"><button draggable="true" class="drag-handle" data-block="${b.id}" title="${t('moveUp')}">⠿</button><button data-action="blockMenu" data-id="${b.id}" aria-label="${t('blockMenu')}">${icon('plus',13)}</button></div>`;let content='';const rendered=inlineMarkdown(b.text,state.pages);if(b.type==='divider')content='<hr>';else if(b.type==='code')content=`<div class="code-label">${e(b.language||t('code'))}</div><pre class="block-render" data-edit="${b.id}"><code>${e(b.text)||t('emptyBlock')}</code></pre>`;else if(b.type==='toggle')content=`<details open><summary>${t('toggle')}</summary><div class="block-render" data-edit="${b.id}">${rendered||`<span class="placeholder">${t('emptyBlock')}</span>`}</div></details>`;else content=`${b.type==='todo'?`<input type="checkbox" class="todo-check" data-todo="${b.id}" aria-label="${t('todo')}" ${b.checked?'checked':''} ${locked?'disabled':''}>`:b.type==='bullet'?'<span class="list-marker">•</span>':b.type==='number'?`<span class="list-marker">${index+1}.</span>`:b.type==='callout'?'<span class="callout-icon">💡</span>':''}<div class="block-render ${b.checked?'checked':''}" data-edit="${b.id}" ${locked?'':'tabindex="0"'}>${rendered||`<span class="placeholder">${t('emptyBlock')}</span>`}</div>`;return `<div class="block block-${e(b.type)} ${b.color?'tinted':''}" data-block-id="${b.id}">${controls}<div class="block-content">${content}</div></div>`;}
function documentPage(){const p=state.page;if(!p)return emptyState(t('pageNotFound'),t('emptyHint'));const parent=state.pages.find(x=>x.id===p.parentId&&!x.deleted),heads=p.blocks.filter(b=>/^h[123]$/.test(b.type)),backlinks=state.pages.filter(x=>!x.deleted&&x.id!==p.id&&x.blocks.some(b=>b.text.includes(`page:${p.id}`)||b.text.includes(`[[${p.title}]]`))),children=state.pages.filter(x=>!x.deleted&&x.parentId===p.id);return `<div class="document-layout ${p.wide?'wide':''}"><div class="document-column">${p.cover?`<div class="page-cover cover-${e(p.cover)}"><div class="cover-lines"></div><span>${e(p.icon)}</span></div>`:''}<article class="document-content"><div class="page-title-tools"><button class="doc-emoji" data-action="editIcon" title="${t('icon')}" ${p.locked||state.busy?'disabled':''}>${e(p.icon)}</button><div>${button(t('cover'),'cover','plain','image',p.locked?'disabled':'')}${p.locked?`<span class="lock-badge">${icon('lock',13)}${t('readonly')}</span>`:''}</div></div><textarea id="page-title" rows="1" placeholder="${t('titleHint')}" aria-label="${t('titleHint')}" ${p.locked||state.busy?'readonly':''}>${e(p.title)}</textarea><div class="page-properties"><div><span>${icon('tag',14)}${t('tag')}</span><div class="tag-list">${p.tags.map(tag=>`<button class="tag-pill" data-action="removeTag" data-tag="${e(tag)}" title="${t('removeTag')}" ${p.locked||state.busy?'disabled':''}>${e(tag)}<span>×</span></button>`).join('')}${p.locked?'':button(t('addTag'),'addTag','small','plus')}</div></div><div><span>${icon('folder',14)}${t('parent')}</span><select id="parent-select" aria-label="${t('parent')}" ${p.locked||state.busy?'disabled':''}><option value="">${t('root')}</option>${state.pages.filter(x=>!x.deleted&&!descendants(state.pages,p.id).has(x.id)).map(x=>`<option value="${x.id}" ${parent?.id===x.id?'selected':''}>${e(x.icon+' '+x.title)}</option>`).join('')}</select></div></div>
 <div class="editor-toolbar"><span>${t(p.database?'database':'editorTools')}</span><div>${iconButton(t('undo'),'undo','undo',state.undo.length&&!p.locked?'':'disabled')}${iconButton(t('redo'),'redo','redo',state.redo.length&&!p.locked?'':'disabled')}${button(t(state.preview?'edit':'preview'),'preview','small','eye')}${button(t('commit'),'commit','small','git',state.busy?'disabled':'')}${iconButton(t('history'),'history','clock')}</div></div>
 ${p.database?databaseHTML(p.database):''}<div class="editor ${state.preview?'preview':''}">${p.blocks.map(blockHTML).join('')}</div>${p.locked||state.preview||state.busy?'':`<button class="add-block" data-action="addBlock">${icon('plus',17)}${t('addBlock')}<small>${t('slashHint')}</small></button>`}
 ${children.length?`<div class="subpages">${children.map(c=>`<button data-action="page" data-id="${c.id}">${e(c.icon)}<span>${e(c.title)}</span>${icon('arrow',14)}</button>`).join('')}</div>`:''}<p class="document-footer">${t('updated')} ${date(p.updatedAt)} · ${p.blocks.reduce((sum,b)=>sum+b.text.length,0)} ${t('words')}</p></article></div><aside class="document-aside"><div class="outline-section"><h3>${t('outline')}</h3>${heads.length?heads.map(h=>`<button data-action="scrollBlock" data-id="${h.id}" style="padding-left:${(Number(h.type[1])-1)*12}px">${e(h.text)}</button>`).join(''):`<p>${t('noOutline')}</p>`}</div><div class="outline-section"><h3>${t('backlinks')} <span>${backlinks.length}</span></h3>${backlinks.length?backlinks.map(x=>`<button data-action="page" data-id="${x.id}">${e(x.icon+' '+x.title)}</button>`).join(''):`<p>${t('noBacklinks')}</p>`}</div><div class="outline-section"><h3>${t('pageInfo')}</h3><p>${t('created')}<br><span>${date(p.createdAt)}</span></p><p>${t('updated')}<br><span>${date(p.updatedAt)}</span></p></div></aside></div>`;}
function databaseHTML(db){const statusColumn=db.columns.find(c=>c.type==='select'),nameColumn=db.columns[0],locked=state.page.locked||state.busy;let rows=db.rows.filter(r=>Object.values(r.values).join(' ').toLocaleLowerCase().includes(state.dbQuery.toLocaleLowerCase()));if(state.dbSort)rows=[...rows].sort((a,b)=>{const column=db.columns.find(c=>c.id===state.dbSort),av=a.values[state.dbSort]||'',bv=b.values[state.dbSort]||'',comp=column?.type==='number'?(Number(av)||0)-(Number(bv)||0):av.localeCompare(bv,'zh');return state.dbDesc?-comp:comp});const viewBar=`<div class="database-toolbar"><div class="view-tabs">${['table','board','list'].map(view=>`<button data-action="dbView" data-view="${view}" class="${state.view===view?'selected':''}">${icon(view,15)}${t(view)}</button>`).join('')}</div><div><input id="db-filter" aria-label="${t('filter')}" placeholder="${t('filter')}" value="${e(state.dbQuery)}">${button(t('newRow'),'newRow','small','plus',locked?'disabled':'')}</div></div>`;
 const cell=(r,c)=>{const value=r.values[c.id]??'',attrs=`data-cell="${r.id}" data-column="${c.id}" ${locked?'disabled':''}`;if(c.type==='checkbox')return `<input type="checkbox" ${attrs} ${value==='true'?'checked':''} aria-label="${e(c.name)}">`;if(c.type==='select'){const options=[...new Set([...(c.options??[]),...db.rows.map(row=>row.values[c.id]).filter(Boolean)])];return `<select ${attrs} aria-label="${e(c.name)}"><option value="">${t('none')}</option>${options.map(option=>`<option ${option===value?'selected':''}>${e(option)}</option>`).join('')}</select>`;}return `<input type="${c.type==='number'?'number':c.type==='date'?'date':c.type==='url'?'url':'text'}" value="${e(value)}" ${attrs} aria-label="${e(c.name)}">`;};
 if(state.view==='table')return `${viewBar}<div class="database-table-wrap"><table class="database-table"><thead><tr>${db.columns.map(c=>`<th><button data-action="dbSort" data-column="${c.id}">${icon(c.type==='select'?'down':c.type==='date'?'clock':'page',13)}${e(c.name)}${state.dbSort===c.id?`<span>${state.dbDesc?'↓':'↑'}</span>`:''}</button>${iconButton(t('deleteColumn'),'removeColumn','close',`data-column="${c.id}" ${locked?'disabled':''}`)}</th>`).join('')}<th>${iconButton(t('addColumn'),'addColumn','plus',locked?'disabled':'')}</th></tr></thead><tbody>${rows.map(r=>`<tr>${db.columns.map(c=>`<td>${cell(r,c)}</td>`).join('')}<td>${iconButton(t('removeRow'),'removeRow','trash',`data-id="${r.id}" ${locked?'disabled':''}`)}</td></tr>`).join('')}</tbody></table>${rows.length?'':`<button class="database-empty" data-action="newRow" ${locked?'disabled':''}>${icon('plus')}${t('noRows')}</button>`}</div>`;
 if(state.view==='board'){const groups=statusColumn?[...new Set([...(statusColumn.options??[]),...rows.map(r=>r.values[statusColumn.id]).filter(Boolean),''])]:[''];return `${viewBar}<div class="board-view">${groups.map((group,i)=>`<section class="board-column" data-group="${e(group)}"><h4><span class="board-dot dot-${i%3}"></span>${e(group)||t('noStatus')}<small>${rows.filter(r=>(r.values[statusColumn?.id]??'')===group).length}</small></h4>${rows.filter(r=>(r.values[statusColumn?.id]??'')===group).map(r=>`<div class="board-card" draggable="${!locked}" data-row-drag="${r.id}">${cell(r,nameColumn)}${db.columns.slice(1).map(c=>`<label><small>${e(c.name)}</small>${cell(r,c)}</label>`).join('')}${iconButton(t('removeRow'),'removeRow','trash',`data-id="${r.id}" ${locked?'disabled':''}`)}</div>`).join('')}<button data-action="newRow" data-group="${e(group)}" ${locked?'disabled':''}>${icon('plus',14)}${t('newRow')}</button></section>`).join('')}</div>`;}
 return `${viewBar}<div class="database-list">${rows.map(r=>`<div>${db.columns.map(c=>`<label><small>${e(c.name)}</small>${cell(r,c)}</label>`).join('')}${iconButton(t('removeRow'),'removeRow','trash',`data-id="${r.id}" ${locked?'disabled':''}`)}</div>`).join('')||emptyState(t('noRows'),t('newRow'),'database')}</div>`;
}
function trashPage(){const pages=state.pages.filter(p=>p.deleted);return `<div class="trash-content"><div class="eyebrow">${icon('trash',15)}${t('trash')}</div><h1>${t('trash')}</h1><p>${t('trashHint')}</p>${pages.length?`<div class="trash-list">${pages.map(p=>`<div><span class="card-emoji">${e(p.icon)}</span><div><strong>${e(p.title)}</strong><small>${date(p.updatedAt)}</small></div>${button(t('restore'),'restorePage','small','restore',`data-id="${p.id}"`)}</div>`).join('')}</div>`:emptyState(t('trashEmpty'),t('trashHint'),'trash')}</div>`;}
function render(){for(const url of assetURLs)URL.revokeObjectURL(url);assetURLs.clear();const focus=document.activeElement?.id,position=document.activeElement?.selectionStart;$('#app').innerHTML=`<div class="app-shell">${sidebar()}<main>${header()}<div class="main-scroll">${state.route==='home'?home():state.route==='trash'?trashPage():documentPage()}</div></main></div>`;bindInputs();hydrateAssets();if(focus&&$('#'+focus)){const el=$('#'+focus);el.focus();if(position!=null&&el.setSelectionRange)el.setSelectionRange(position,position);}resizeAll();}
function renderSaveState(){const el=$('#save-state');if(el){el.classList.toggle('failed',!!state.saveError);el.innerHTML=state.saveError?`${icon('info',14)}${t('saveError')}`:state.saving?`${icon('clock',14)}${t('saving')}`:`<span class="status-dot"></span>${t('saved')}`;}}
function resize(el){el.style.height='auto';el.style.height=el.scrollHeight+'px';}
function resizeAll(){document.querySelectorAll('textarea').forEach(resize);}
function snapshot(){if(state.page){state.undo.push(clone(state.page));if(state.undo.length>60)state.undo.shift();state.redo=[];}}
function changed(){state.dirty=true;state.editSeq++;state.saveError='';try{localStorage.setItem(recoveryKey(),JSON.stringify(state.page));}catch{}clearTimeout(saveTimer);saveTimer=setTimeout(()=>flush().catch(error=>toast(error.message,true)),600);renderSaveState();}
async function flush(){clearTimeout(saveTimer);if(state.saving)await state.saving;if(!state.dirty||!state.page)return;const p=clone(state.page),seq=state.editSeq,work=state.config.activeId,key=recoveryKey();state.saving=api('save',{workspaceId:work,page:p});renderSaveState();try{const saved=await state.saving;if(state.page?.id===saved.id&&state.config.activeId===work){state.page.revision=saved.revision;state.page.updatedAt=saved.updatedAt;state.page.createdAt=saved.createdAt;}const i=state.pages.findIndex(p=>p.id===saved.id);if(i>=0)state.pages[i]=saved;else state.pages.push(saved);state.dirty=state.editSeq!==seq;if(!state.dirty){localStorage.removeItem(key);}else{try{localStorage.setItem(key,JSON.stringify(state.page));}catch{}}state.saveError='';}catch(error){state.saveError=error.message;throw error;}finally{state.saving=null;renderSaveState();}if(state.dirty)return flush();}
async function refresh(){const [pages,stats,status]=await Promise.all([request('pages'),request('stats'),request('status')]);state.pages=pages;state.stats=stats;state.status=status;}
async function navigate(route){await flush();state.route=route;state.sidebar=false;state.query='';state.preview=false;state.undo=[];state.redo=[];state.saveError='';state.page=state.pages.find(p=>p.id===route&&!p.deleted)?clone(state.pages.find(p=>p.id===route)):null;if(state.page){const key=recoveryKey();try{const draft=JSON.parse(localStorage.getItem(key)||'null');if(draft){if(draft.revision===state.page.revision){state.page=draft;changed();toast(t('saving'));}else{toast(t('unsavedWarning'),true);await request('save',{page:{...draft,id:'',revision:0,title:draft.title+' · 恢复副本',parentId:''}});localStorage.removeItem(key);await refresh();}}}catch(error){toast(error.message,true);}}render();$('.main-scroll')?.scrollTo(0,0);}
async function createPage(p=makePage(t('emptyTitle'))){await flush();const saved=await request('save',{page:p});state.pages.push(saved);await navigate(saved.id);setTimeout(()=>{$('#page-title')?.focus();$('#page-title')?.select();},20);}
function modal(title,body,wide=false){$('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal ${wide?'modal-wide':''}" role="dialog" aria-modal="true" aria-label="${e(title)}"><div class="modal-header"><h2>${e(title)}</h2>${iconButton(t('close'),'closeModal','close')}</div><div class="modal-body">${body}</div></section></div>`;setTimeout(()=>$('.modal input:not([type=checkbox]),.modal button')?.focus(),20);}
function closeModal(){$('#modal-root').replaceChildren();}
function promptField(title,label,initial,onConfirm,type='text'){modal(title,`<form id="prompt-form"><label class="form-field">${e(label)}<input name="value" type="${type}" value="${e(initial)}" required autocomplete="off"></label><div class="modal-footer">${button(t('cancel'),'closeModal')}${button(t('confirm'),'','primary','', 'type="submit"')}</div></form>`);$('#prompt-form').onsubmit=async event=>{event.preventDefault();try{await onConfirm(new FormData(event.target).get('value'));closeModal();}catch(error){toast(error.message,true)}};}
function showSearch(){modal(t('search'),`<div class="search-dialog-input">${icon('search',21)}<input id="global-search" placeholder="${t('searchHint')}" autocomplete="off"></div><div id="search-results">${searchResults('')}</div>`);$('#global-search').oninput=event=>{$('#search-results').innerHTML=searchResults(event.target.value)};}
function searchResults(query){const found=filterPages(state.pages,query).slice(0,25);return found.map(p=>`<button class="search-result" data-action="page" data-id="${p.id}"><span class="card-emoji">${e(p.icon)}</span><span><strong>${e(p.title)}</strong><small>${e(p.tags.join(' · ')||p.blocks?.[0]?.text?.slice(0,70)||'')}</small></span>${icon('arrow',15)}</button>`).join('')||emptyState(t('noResults'),t('noResultsHint'),'search');}
function showTemplates(){modal(t('templatesTitle'),`<div class="template-grid">${templates().map(template=>`<button data-action="useTemplate" data-template="${template.key}"><span>${template.icon}</span><h3>${t(template.key)}</h3><p>${e(template.description)}</p><small>${t('useTemplate')}${icon('arrow',14)}</small></button>`).join('')}</div>`,true);}
function workspaceMenu(){modal(t('workspaces'),`<div class="workspace-list">${state.config.workspaces.map(w=>`<button data-action="activate" data-id="${w.id}"><span class="workspace-avatar">${e(w.name.slice(0,1))}</span><span><strong>${e(w.name)}</strong><small>${w.remote?e(new URL(w.remote.startsWith('https:')?w.remote:'https://localhost').host):t('localOnly')}</small></span>${w.id===state.config.activeId?icon('check'):''}</button>`).join('')}</div>${button(t('newWorkspace'),'newWorkspace','primary','plus')}`);}
function workspaceForm(){modal(t('newWorkspace'),`<form id="workspace-form"><label class="form-field">${t('workspaceName')}<input name="name" required placeholder="${t('personal')}"></label><label class="form-field">${t('remote')}<input name="remote" placeholder="https://github.com/username/notes.git"><small>${t('remoteHint')}</small></label><div class="form-columns"><label class="form-field">${t('branch')}<input name="branch" value="main" required></label><label class="form-field">${t('workspace')}<select name="mode"><option value="">${t('fresh')}</option><option value="clone">${t('clone')}</option></select></label></div><label class="form-field">${t('username')}<input name="username" autocomplete="off"></label><label class="form-field">${t('token')}<input name="token" type="password" autocomplete="off"><small>${t('tokenHint')}</small></label><div class="modal-footer">${button(t('cancel'),'closeModal')}${button(t('create'),'','primary','plus','type="submit"')}</div></form>`);$('#workspace-form').onsubmit=async event=>{event.preventDefault();const submit=event.target.querySelector('[type=submit]');submit.disabled=true;submit.querySelector('span').textContent=t('savingWorkspace');try{await flush();const form=Object.fromEntries(new FormData(event.target));await api('createWorkspace',form);state.config=await api('bootstrap');await refresh();closeModal();await navigate('home');}catch(error){toast(error.message,true);submit.disabled=false;submit.querySelector('span').textContent=t('create');}};}
function showImport(){modal(t('importTitle'),`<div class="import-drop">${icon('download',36)}<h3>${t('importDesc')}</h3><p>${t('dropHint')}</p>${button(t('chooseFile'),'chooseImport','primary','download')}</div><label class="form-field import-format">${t('importFormat')}<select id="import-format"><option value="">${t('autoFormat')}</option><option value="md">${t('plainNotes')}</option><option value="csv">${t('databaseTable')}</option><option value="html">${t('webNotes')}</option></select><small>${t('importFormatHint')}</small></label><div class="import-note"><h4>${t('notion')}</h4><p>${t('importGuide')}</p><small>${t('importLimits')}</small></div>`);}
async function doImport(){const format=$('#import-format')?.value||'';const file=await pickFile();if(!file)return;if(format){const name=file.name.replace(/\.[^.]+$/,'');file.name=(/^\d+$/.test(name)?t('importedNote'):name)+'.'+format;}const btn=$('[data-action="chooseImport"]');if(btn){btn.disabled=true;btn.querySelector('span').textContent=t('importing');}try{await flush();const report=await request('import',file);await refresh();await navigate('home');modal(t('importReport'),`<div class="import-success">${icon('check',32)}<h3>${t('importSuccess')}</h3><p>${report.pages} ${t('pageCount')} · ${report.assets} ${t('assetsSize')}</p></div>${report.warnings.map(w=>`<p class="report-warning">${icon('info',16)}${e(w)}</p>`).join('')}<div class="modal-footer">${button(t('done'),'closeModal','primary')}</div>`);}catch(error){if(btn){btn.disabled=false;btn.querySelector('span').textContent=t('chooseFile')}throw error;}}
function showSettings(tab='workspaces'){const w=workspace(),p=state.config.preferences;const tabs=['workspaces','appearance','data','about'];let body='';if(tab==='workspaces')body=`<form id="repo-form"><label class="form-field">${t('workspaceName')}<input name="name" value="${e(w.name)}" required></label><label class="form-field">${t('remote')}<input name="remote" value="${e(w.remote)}" placeholder="https://github.com/username/notes.git"><small>${t('remoteHint')}</small></label><label class="form-field">${t('branch')}<input name="branch" value="${e(w.branch)}" readonly></label><p class="form-hint">${t('syncHint')}</p><div class="modal-footer">${button(t('newWorkspace'),'newWorkspace','plain','plus')}${button(t('save'),'','primary','','type="submit"')}</div></form><hr><form id="auth-form"><h3>${t('credentials')}</h3><label class="form-field">${t('username')}<input name="username" autocomplete="off"></label><label class="form-field">${t('token')}<input name="token" type="password" autocomplete="off"><small>${t('tokenHint')}</small></label><div class="modal-footer">${button(t('saveCredentials'),'','plain','','type="submit"')}</div></form>`;
 if(tab==='appearance')body=`<div class="preferences"><h3>${t('theme')}</h3><div class="theme-options">${['light','dark','system'].map(theme=>`<button class="${p.theme===theme?'selected':''}" data-action="preference" data-key="theme" data-value="${theme}"><div class="theme-preview ${theme}"><i></i><span></span></div>${t(theme)}${p.theme===theme?icon('check',13):''}</button>`).join('')}</div><label class="form-field">${t('language')}<select id="pref-language"><option value="zh-CN" ${p.language==='zh-CN'?'selected':''}>简体中文</option><option value="zh-TW" ${p.language==='zh-TW'?'selected':''}>繁體中文</option></select></label><label class="form-field">${t('font')}<select id="pref-font">${['sans','serif','mono'].map(font=>`<option value="${font}" ${p.font===font?'selected':''}>${t(font)}</option>`).join('')}</select></label></div>`;
 if(tab==='data')body=`<h3>${t('disk')}</h3><div class="disk-total">${formatStorage()}</div><div class="disk-breakdown">${['notes','assets','git'].map(key=>`<div><span>${t(key==='notes'?'notesSize':key==='assets'?'assetsSize':'gitSize')}</span><strong>${byteSize(state.stats?.[key]||0)}</strong></div>`).join('')}</div><label class="form-field">${t('dataPath')}<code>${e(state.stats?.path)}</code></label><hr><h3>${t('data')}</h3><p class="form-hint">${t('exportHint')}</p><div class="data-actions">${button(t('import'),'import','plain','download')}${button(t('export'),'export','primary','upload')}</div>`;
 if(tab==='about')body=`<div class="about-app"><div class="brand-mark">笺</div><h2>${t('app')}</h2><p>${t('tagline')}</p><span class="tag-pill">${t('version')}</span><p>${t('offlineReady')}</p><small>${t('importLimits')}</small></div>`;
 modal(t('settings'),`<div class="settings-layout"><nav>${tabs.map(key=>`<button data-action="settings" data-tab="${key}" class="${tab===key?'selected':''}">${icon(key==='workspaces'?'git':key==='appearance'?'sun':key==='data'?'database':'info',16)}${t(key)}</button>`).join('')}</nav><div class="settings-content">${body}</div></div>`,true);
 if($('#repo-form'))$('#repo-form').onsubmit=async event=>{event.preventDefault();const form=Object.fromEntries(new FormData(event.target));state.config=await request('updateWorkspace',{workspace:{...w,...form}}).catch(error=>{toast(error.message,true);throw error});await refresh();render();showSettings(tab);toast(t('saved'));};if($('#auth-form'))$('#auth-form').onsubmit=async event=>{event.preventDefault();try{await request('credentials',Object.fromEntries(new FormData(event.target)));event.target.reset();toast(t('authSet'));}catch(error){toast(error.message,true)}};
 if($('#pref-language'))$('#pref-language').onchange=event=>setPreference('language',event.target.value);if($('#pref-font'))$('#pref-font').onchange=event=>setPreference('font',event.target.value);
}
async function setPreference(key,value){state.config=await request('preferences',{preferences:{...state.config.preferences,[key]:value}});applyPreferences();render();showSettings('appearance');}
async function showHistory(){await flush();const history=await request('history',{id:state.page.id});modal(t('history'),history.length?`<p class="form-hint">${t('restoreVersionHint')}</p><div class="history-list">${history.map(v=>`<div><div class="history-point"></div><div><strong>${e(v.message)}</strong><small>${e(v.author)} · ${date(v.date)} · <code>${v.commit.slice(0,7)}</code></small></div>${button(t('restoreVersion'),'restoreVersion','small','restore',`data-commit="${v.commit}"`)}</div>`).join('')}</div>`:emptyState(t('historyEmpty'),t('historyHint'),'clock'));}
function moreMenu(){const p=state.page;modal(t('more'),`<div class="action-menu">${button(t(p.favorite?'unfavorite':'favorite'),'favorite','plain','star')}${button(t('subpage'),'subpage','plain','plus',`data-id="${p.id}"`)}${button(t('duplicate'),'duplicate','plain','copy')}${button(t(p.locked?'unlock':'lock'),'lock','plain','lock')}${button(t('wide'),'wide','plain','grid')}${button(t('exportPage'),'exportPage','plain','upload')}${button(t('history'),'history','plain','clock')}<hr>${button(t('delete'),'delete','danger','trash')}</div>`);}
const blockTypes=['paragraph','h1','h2','h3','bullet','number','todo','quote','callout','code','divider','toggle','image','bookmark'];
function showBlockMenu(id=''){state.menu=id;modal(t('blockMenu'),`<div class="block-type-menu">${blockTypes.map(type=>`<button data-action="setBlockType" data-type="${type}" data-id="${id}"><span class="block-type-icon">${type==='paragraph'?'文':type==='h1'?'大':type==='h2'?'中':type==='h3'?'小':type==='todo'?'☑':type==='code'?'{}':type==='divider'?'—':type==='quote'?'❝':type==='callout'?'💡':icon(type==='image'?'image':type==='bookmark'?'page':'list',17)}</span><strong>${t(type)}</strong></button>`).join('')}</div>${id?`<div class="modal-footer">${button(t('moveUp'),'blockUp','small','',`data-id="${id}"`)}${button(t('moveDown'),'blockDown','small','',`data-id="${id}"`)}${button(t('removeBlock'),'removeBlock','danger','trash',`data-id="${id}"`)}</div>`:''}`);}
function openEditor(id){if(state.page?.locked||state.preview||state.busy)return;const b=state.page.blocks.find(b=>b.id===id);if(!b||b.type==='divider')return;const target=document.querySelector(`[data-edit="${id}"]`);if(!target||target.querySelector('textarea'))return;const before=b.text;target.innerHTML=`<textarea class="block-input" data-input-block="${id}" placeholder="${t('emptyBlock')}" aria-label="${t(b.type)}">${e(b.text)}</textarea><div class="inline-tools"><button data-format="bold" title="${t('bold')}"><b>粗</b></button><button data-format="italic" title="${t('italic')}"><i>斜</i></button><button data-format="link" title="${t('link')}">${icon('attach',13)}</button><span>${t('markdownHint')}</span></div>`;const input=target.querySelector('textarea');resize(input);input.focus();input.setSelectionRange(input.value.length,input.value.length);let captured=false;input.oninput=()=>{if(!captured){snapshot();captured=true;}b.text=input.value;changed();resize(input);if(input.value==='/'){showBlockMenu(id);}};input.onblur=()=>{setTimeout(()=>{if(!target.contains(document.activeElement)){target.innerHTML=inlineMarkdown(b.text,state.pages)||`<span class="placeholder">${t('emptyBlock')}</span>`;hydrateAssets();}},120);};input.onkeydown=event=>{if(event.key==='Escape'){event.preventDefault();input.blur();}if(event.key==='Enter'&&!event.shiftKey&&b.type!=='code'){event.preventDefault();snapshot();const i=state.page.blocks.indexOf(b);state.page.blocks.splice(i+1,0,{id:uid(),type:['todo','bullet','number'].includes(b.type)?b.type:'paragraph',text:'',checked:false});changed();render();openEditor(state.page.blocks[i+1].id);}if(event.key==='Backspace'&&!input.value&&state.page.blocks.length>1){event.preventDefault();snapshot();const i=state.page.blocks.indexOf(b);state.page.blocks.splice(i,1);changed();render();openEditor(state.page.blocks[Math.max(0,i-1)]?.id);}};target.querySelectorAll('[data-format]').forEach(button=>button.onmousedown=event=>{event.preventDefault();const start=input.selectionStart,end=input.selectionEnd,selection=input.value.slice(start,end);snapshot();const wrapped=button.dataset.format==='bold'?`**${selection}**`:button.dataset.format==='italic'?`*${selection}*`:`[[${selection}]]`;input.setRangeText(wrapped,start,end,'select');b.text=input.value;changed();resize(input);input.focus();});}
async function hydrateAssets(){for(const el of document.querySelectorAll('[data-asset]')){if(el.dataset.loaded)continue;el.dataset.loaded='true';try{const result=await request('asset',{name:el.dataset.asset}),name=result.name,ext=name.split('.').pop().toLowerCase(),mime={png:'image/png',jpg:'image/jpeg',jpeg:'image/jpeg',gif:'image/gif',webp:'image/webp',avif:'image/avif'}[ext];if(!el.isConnected)continue;const blob=URL.createObjectURL(new Blob([decodeBase64(result.data)],{type:mime||'application/octet-stream'}));assetURLs.add(blob);el.innerHTML=mime?`<img src="${blob}" alt="${t('image')}" loading="lazy">`:`<a class="attachment-link" href="${blob}" download="${e(name)}">${icon('attach',16)}${e(name)}</a>`;el.dataset.blob=blob;}catch(error){el.textContent=t('assetFailed');}}}
function bindInputs(){if($('#home-search'))$('#home-search').oninput=event=>{state.query=event.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(render,120);};if($('#tag-filter'))$('#tag-filter').onchange=event=>{state.tag=event.target.value;render()};if($('#home-sort'))$('#home-sort').onchange=event=>{state.sort=event.target.value;render()};if($('#page-title'))$('#page-title').oninput=event=>{snapshot();state.page.title=event.target.value;changed();resize(event.target);};if($('#parent-select'))$('#parent-select').onchange=event=>{snapshot();state.page.parentId=event.target.value;changed();};document.querySelectorAll('[data-todo]').forEach(input=>input.onchange=()=>{snapshot();state.page.blocks.find(b=>b.id===input.dataset.todo).checked=input.checked;changed();render();});if($('#db-filter'))$('#db-filter').oninput=event=>{state.dbQuery=event.target.value;render();};document.querySelectorAll('[data-cell]').forEach(input=>input.onchange=()=>{snapshot();const row=state.page.database.rows.find(r=>r.id===input.dataset.cell);row.values[input.dataset.column]=input.type==='checkbox'?String(input.checked):input.value;changed();});}
async function handleAction(action,el){
 const mutations=new Set(['newPage','subpage','favorite','rowFavorite','duplicate','lock','wide','delete','confirmDelete','addTag','removeTag','editIcon','cover','setCover','addBlock','setBlockType','blockUp','blockDown','removeBlock','undo','redo','newRow','removeRow','addColumn','removeColumn','confirmRemoveColumn','restoreVersion','import','chooseImport']);
 if(state.busy&&mutations.has(action)){toast(t('syncing'));return;}
 switch(action){case 'sidebar':state.sidebar=!state.sidebar;render();break;case 'home':closeModal();await navigate('home');break;case 'page':closeModal();await navigate(el.dataset.id);break;case 'newPage':closeModal();await createPage();break;case 'subpage':closeModal();state.expanded.add(el.dataset.id);await createPage({...makePage(t('emptyTitle'),el.dataset.id)});break;case 'expand':state.expanded.has(el.dataset.id)?state.expanded.delete(el.dataset.id):state.expanded.add(el.dataset.id);render();break;
 case 'search':showSearch();break;case 'templates':showTemplates();break;case 'useTemplate':{const template=templates().find(x=>x.key===el.dataset.template);closeModal();await createPage({...template.make(),icon:template.icon});break;}case 'workspaceMenu':workspaceMenu();break;case 'newWorkspace':workspaceForm();break;case 'activate':await flush();state.config=await api('activate',{workspaceId:el.dataset.id});state.dirty=false;state.page=null;await refresh();closeModal();await navigate('home');break;case 'settings':await flush();await refresh();showSettings(el.dataset.tab||'workspaces');break;case 'preference':await setPreference(el.dataset.key,el.dataset.value);break;case 'import':showImport();break;case 'chooseImport':await doImport();break;case 'export':await flush();toast(t('exporting'));{const result=await request('export'),saved=await saveFile(result.name,result.data);if(saved)toast(saved);}break;
 case 'trash':closeModal();await flush();await refresh();await navigate('trash');break;case 'restorePage':await request('trash',{id:el.dataset.id,deleted:false});await refresh();render();toast(t('restore'));break;case 'allPages':state.favorites=false;render();break;case 'favoritesOnly':state.favorites=true;render();break;case 'closeModal':closeModal();break;case 'more':moreMenu();break;case 'retry':await flush();render();break;
 case 'favorite':snapshot();state.page.favorite=!state.page.favorite;changed();await flush();closeModal();render();break;case 'rowFavorite':{const p=clone(state.pages.find(p=>p.id===el.dataset.id));p.favorite=!p.favorite;await request('save',{page:p});await refresh();render();break;}
 case 'duplicate':{const p=clone(state.page);p.title+=' · 副本';p.id='';p.revision=0;p.favorite=false;closeModal();await createPage(p);break;}
 case 'lock':snapshot();state.page.locked=!state.page.locked;changed();closeModal();await flush();render();break;case 'wide':snapshot();state.page.wide=!state.page.wide;changed();closeModal();render();break;case 'delete':modal(t('delete'),`<p>${t('deleteWarning')}</p><div class="modal-footer">${button(t('cancel'),'closeModal')}${button(t('deleteConfirm'),'confirmDelete','danger','trash')}</div>`);break;case 'confirmDelete':await flush();await request('trash',{id:state.page.id,deleted:true});await refresh();closeModal();await navigate('home');break;
 case 'addTag':promptField(t('addTag'),t('tag'),'',value=>{snapshot();if(!state.page.tags.includes(value.trim()))state.page.tags.push(value.trim());changed();render();});break;case 'removeTag':snapshot();state.page.tags=state.page.tags.filter(tag=>tag!==el.dataset.tag);changed();render();break;case 'editIcon':promptField(t('icon'),t('icon'),state.page.icon,value=>{snapshot();state.page.icon=value.slice(0,12);changed();render();});break;case 'cover':modal(t('cover'),`<div class="cover-choices">${['','garden','ocean','sunset'].map(cover=>`<button data-action="setCover" data-cover="${cover}"><div class="cover-${cover}"></div>${t(cover?cover+'Cover':'noCover')}</button>`).join('')}</div>`);break;case 'setCover':snapshot();state.page.cover=el.dataset.cover;changed();closeModal();render();break;
 case 'preview':state.preview=!state.preview;render();break;case 'addBlock':showBlockMenu();break;case 'blockMenu':showBlockMenu(el.dataset.id);break;case 'setBlockType':{const type=el.dataset.type,id=el.dataset.id;snapshot();let b=state.page.blocks.find(x=>x.id===id);if(!b){b={id:uid(),type:'paragraph',text:''};state.page.blocks.push(b);}b.type=type;if(b.text==='/')b.text='';if(type==='image'){closeModal();const file=await pickFile(true);if(file){const asset=await request('attach',file);b.type='paragraph';b.text=`![${file.name}](asset:${asset.name})`;}else{b.type='paragraph';}}else if(type==='bookmark'){b.type='paragraph';b.text='[网页链接](https://example.com)';}changed();closeModal();render();if(type!=='divider'&&type!=='image')openEditor(b.id);break;}
 case 'removeBlock':snapshot();state.page.blocks=state.page.blocks.filter(b=>b.id!==el.dataset.id);changed();closeModal();render();break;case 'blockUp':case 'blockDown':{snapshot();const i=state.page.blocks.findIndex(b=>b.id===el.dataset.id),next=i+(action==='blockUp'?-1:1);if(next>=0&&next<state.page.blocks.length)[state.page.blocks[i],state.page.blocks[next]]=[state.page.blocks[next],state.page.blocks[i]];changed();closeModal();render();break;}
 case 'undo':case 'redo':{const stack=action==='undo'?state.undo:state.redo,other=action==='undo'?state.redo:state.undo;if(!stack.length||state.page.locked)break;other.push(clone(state.page));const revision=state.page.revision;state.page=stack.pop();state.page.revision=revision;changed();render();break;}
 case 'scrollBlock':document.querySelector(`[data-block-id="${el.dataset.id}"]`)?.scrollIntoView({behavior:'smooth',block:'start'});break;case 'commit':case 'sync':state.busy=true;render();toast(t(action==='sync'?'syncing':'committing'));try{await flush();const result=await request(action);await refresh();if(state.page){state.page=clone(state.pages.find(p=>p.id===state.page.id));}toast(result.message);}finally{state.busy=false;render();}break;case 'history':closeModal();await showHistory();break;case 'restoreVersion':await flush();state.page=await request('restore',{id:state.page.id,commit:el.dataset.commit});await refresh();closeModal();render();toast(t('restore'));break;
 case 'exportPage':await flush();closeModal();{const content='# '+state.page.title+'\n\n'+toMarkdown(state.page.blocks);await saveFile(state.page.title.replace(/[\\/:*?"<>|]/g,'_')+'.md',encodeBase64(new TextEncoder().encode(content)));}break;
 case 'dbView':state.view=el.dataset.view;render();break;case 'dbSort':state.dbDesc=state.dbSort===el.dataset.column?!state.dbDesc:false;state.dbSort=el.dataset.column;render();break;case 'newRow':{if(state.page.locked)break;snapshot();const values={};const column=state.page.database.columns.find(c=>c.type==='select');if(column&&el.dataset.group)values[column.id]=el.dataset.group;state.page.database.rows.push({id:uid(),values});changed();render();break;}case 'removeRow':snapshot();state.page.database.rows=state.page.database.rows.filter(r=>r.id!==el.dataset.id);changed();render();break;case 'addColumn':showColumnForm();break;case 'removeColumn':modal(t('deleteColumn'),`<p>${t('removeColumnConfirm')}</p><div class="modal-footer">${button(t('cancel'),'closeModal')}${button(t('deleteColumn'),'confirmRemoveColumn','danger','trash',`data-column="${el.dataset.column}"`)}</div>`);break;case 'confirmRemoveColumn':{if(state.page.database.columns.length<=1)break;snapshot();state.page.database.columns=state.page.database.columns.filter(c=>c.id!==el.dataset.column);for(const r of state.page.database.rows)delete r.values[el.dataset.column];changed();closeModal();render();break;}
 }
}
function showColumnForm(){modal(t('addColumn'),`<form id="column-form"><label class="form-field">${t('columnName')}<input name="name" required></label><label class="form-field">${t('columnType')}<select name="type">${['text','select','date','checkbox','number','url'].map(type=>`<option value="${type}">${t(type==='number'?'numberProperty':type)}</option>`).join('')}</select></label><label class="form-field">${t('select')}<input name="options" placeholder="待开始，进行中，已完成"></label><div class="modal-footer">${button(t('save'),'','primary','','type="submit"')}</div></form>`);$('#column-form').onsubmit=event=>{event.preventDefault();const form=Object.fromEntries(new FormData(event.target));snapshot();state.page.database.columns.push({id:uid(),name:form.name,type:form.type,options:form.options.split(/[,，]/).map(s=>s.trim()).filter(Boolean)});changed();closeModal();render();};}
document.addEventListener('click',async event=>{const el=event.target.closest('[data-action]');if(el){event.preventDefault();if(el.disabled)return;try{await handleAction(el.dataset.action,el);}catch(error){toast(error.message||t('operationFailed'),true);}return;}const link=event.target.closest('a');if(link){const href=link.getAttribute('href');if(href.startsWith('page:')){event.preventDefault();navigate(href.slice(5)).catch(error=>toast(error.message,true));}else if(href.startsWith('http')||href.startsWith('mailto:')){event.preventDefault();if(safeURL(href))openExternal(href).catch(error=>toast(error.message,true));}return;}const block=event.target.closest('[data-edit]');if(block&&!event.target.closest('textarea,[data-format]'))openEditor(block.dataset.edit);});
document.addEventListener('keydown',event=>{const command=event.ctrlKey||event.metaKey;if(command&&event.key.toLowerCase()==='k'){event.preventDefault();showSearch();}if(command&&event.key.toLowerCase()==='s'){event.preventDefault();flush().then(()=>toast(t('saved'))).catch(error=>toast(error.message,true));}if(event.key==='Escape'){closeModal();state.sidebar=false;}if(event.key==='Tab'&&$('.modal')){const nodes=[...$('.modal').querySelectorAll('button:not([disabled]),input,select,textarea,a[href]')];if(nodes.length){const first=nodes[0],last=nodes.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}}if(event.key==='Enter'&&event.target.matches('[data-edit]')){event.preventDefault();openEditor(event.target.dataset.edit);}});
document.addEventListener('dragstart',event=>{const handle=event.target.closest('[data-block]');if(handle){draggedBlock=handle.dataset.block;event.dataTransfer.setData('text/plain',draggedBlock);}const row=event.target.closest('[data-row-drag]');if(row)event.dataTransfer.setData('application/qingjian-row',row.dataset.rowDrag);});
document.addEventListener('dragover',event=>{if(event.target.closest('[data-block-id],.board-column'))event.preventDefault();});
document.addEventListener('drop',event=>{if(state.page?.locked||state.busy)return;const target=event.target.closest('[data-block-id]');if(target&&draggedBlock){event.preventDefault();snapshot();const from=state.page.blocks.findIndex(b=>b.id===draggedBlock),to=state.page.blocks.findIndex(b=>b.id===target.dataset.blockId);if(from>=0&&to>=0){const [block]=state.page.blocks.splice(from,1);state.page.blocks.splice(to,0,block);changed();render();}draggedBlock=null;}const column=event.target.closest('.board-column');if(column){const id=event.dataTransfer.getData('application/qingjian-row'),row=state.page.database.rows.find(r=>r.id===id),property=state.page.database.columns.find(c=>c.type==='select');if(row&&property){snapshot();row.values[property.id]=column.dataset.group;changed();render();}}});
window.addEventListener('beforeunload',event=>{if(state.dirty){event.preventDefault();event.returnValue='';}});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&state.dirty)flush().catch(()=>{});});
matchMedia('(prefers-color-scheme: dark)').addEventListener('change',()=>{if(state.config?.preferences.theme==='system')applyPreferences();});
async function start(){try{state.config=await api('bootstrap');applyPreferences();await refresh();render();}catch(error){$('#app').innerHTML=`<div class="fatal-error">${icon('info',36)}<h2>${t('operationFailed')}</h2><p>${e(error.message)}</p>${button(t('retry'),'reload','primary')}</div>`;$('[data-action="reload"]').onclick=()=>location.reload();}}
start();
